// Une requête par flux de marchés publics ACTIF.
//
// Le filtrage sur `statut = 'actif'` n'est pas décoratif : la règle du § 10.4
// veut qu'aucune liaison ne collecte sans qualification humaine nominative, et
// jusqu'au 24.08 aucun code ne lisait ce statut. Il est lu ici.
const runId = $('Ouvrir le run').first().json.run_id;
const JOURS = 60;   // un appel d'offres court dure rarement plus de deux mois

const CHAMPS = ["publication-number","notice-title","publication-date","notice-type",
  "buyer-name","buyer-country","buyer-city","buyer-email","buyer-internet-address",
  "deadline-receipt-tender-date-lot","estimated-value-lot","estimated-value-cur-lot",
  "classification-cpv","contract-nature"];

const aaaammjj = d => '' + d.getUTCFullYear()
  + String(d.getUTCMonth()+1).padStart(2,'0') + String(d.getUTCDate()).padStart(2,'0');
const fin = new Date();
const debut = new Date(fin.getTime() - JOURS*86400000);

const sorties = [];
for (const item of $input.all()) {
  const f = item.json;
  const params = typeof f.parametres === 'string' ? JSON.parse(f.parametres) : (f.parametres ?? {});
  const cpv = params.cpv;
  if (!cpv) continue;
  sorties.push({ json: {
    run_id: runId, flux_id: f.flux_id, sector_code: f.sector_code, cpv,
    corps: { query: `classification-cpv IN (${cpv}) AND publication-date >= ${aaaammjj(debut)} `
                  + `AND publication-date <= ${aaaammjj(fin)}`,
             limit: 250, fields: CHAMPS }
  }});
}
if (!sorties.length) throw new Error("aucun flux de marchés publics actif — vérifier flux_sources.statut");
return sorties;

// Mise à plat des avis, un item de sortie par avis.
//
// Mode GLOBAL et non « une fois par item » : une réponse de TED porte jusqu'à
// 250 avis, et un nœud en mode par-item doit rendre exactement un objet. C'est
// la cause de l'échec constaté au premier essai (« A 'json' property isn't an
// object »). On itère donc soi-même, en réappariant chaque réponse à la requête
// qui l'a produite par `pairedItem` — jamais par position, l'ordre d'arrivée
// des appels HTTP n'étant pas garanti.
//
// TED rend beaucoup de champs en DICTIONNAIRE DE LANGUES ou en liste : le titre
// arrive sous {fra: "...", eng: "..."}, l'acheteur parfois en tableau. `txt`
// déplie cela dans un ordre de préférence déclaré, français d'abord — sans quoi
// le tableau de bord afficherait des objets JSON.
function txt(v, langues = ['fra','eng','deu','mul']) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.length ? txt(v[0], langues) : null;
  if (typeof v === 'object') {
    for (const lg of langues) if (v[lg]) return txt(v[lg], langues);
    for (const x of Object.values(v)) { const r = txt(x, langues); if (r) return r; }
  }
  return String(v);
}
const dateDe = v => { const s = txt(v); return s && s.length >= 10 ? s.slice(0,10) : null; };
const nombre = v => { const n = parseFloat(txt(v)); return Number.isFinite(n) ? n : null; };

const sorties = [];
const lignes = $input.all();
for (let i = 0; i < lignes.length; i++) {
  const rep = lignes[i].json;
  const t = $('Préparer les requêtes').itemMatching(i).json;
  for (const a of (rep.notices ?? [])) {
    const num = a['publication-number'];
    if (!num) continue;
    const ntype = txt(a['notice-type']) || '';
    // cn-* = appel à candidature ; can-* = avis d'ATTRIBUTION, déjà décidé.
    // La distinction fait tout l'écran Actions : proposer un marché attribué
    // ferait perdre son temps au décideur.
    const ouvert = ntype.startsWith('cn');
    let cpvs = a['classification-cpv'];
    cpvs = Array.isArray(cpvs) ? [...new Set(cpvs.map(String))].sort() : null;
    sorties.push({ json: {
      publication_number: num, flux_id: t.flux_id, sector_code: t.sector_code,
      notice_type: ntype, est_appel_ouvert: ouvert,
      date_publication: dateDe(a['publication-date']),
      date_limite: dateDe(a['deadline-receipt-tender-date-lot']),
      titre: (txt(a['notice-title']) || '').slice(0, 600),
      acheteur: txt(a['buyer-name']), acheteur_pays: txt(a['buyer-country']),
      acheteur_ville: txt(a['buyer-city']), acheteur_courriel: txt(a['buyer-email']),
      acheteur_site: txt(a['buyer-internet-address']),
      valeur_estimee: nombre(a['estimated-value-lot']),
      devise: txt(a['estimated-value-cur-lot']),
      cpv: cpvs ? '{' + cpvs.join(',') + '}' : null,
      nature_contrat: txt(a['contract-nature']),
      url: 'https://ted.europa.eu/fr/notice/-/detail/' + num,
      raw_ref: 'run ' + t.run_id + ' · ' + t.flux_id + ' · CPV ' + t.cpv,
      _flux: t.flux_id, _total_disponible: rep.totalNoticeCount ?? null
    }});
  }
}
if (!sorties.length) throw new Error('aucun avis rendu par TED — requête ou fenêtre à vérifier');
return sorties;
